import Foundation
import MeroKit
import XCTest

/// Web invitations: tokens generated by the web apps' own code
/// (`bs58` + `fflate` `deflateSync(…, { level: 9 })`, as in
/// apps/mero-design/app/src/utils/invitation.ts `encodeInvitationObject`).
final class AppInvitationTests: XCTestCase {
    /// `{ invitation: <signed>, __teamName: "Design Team ✨" }`: mero-design's payload.
    static let designToken =
        "2GwyBbBnCnvyRuScxi99tFjch1PVttFHKohW3h5opAJoVRsfDfL1p8kqtQpsQuXv49V3j4QxzgKFAA3MeQHGYaSy2babRoM8VdPV5cQHqGkk"
        + "oHbvXgftBUc6GEVFTffVJvJfYtMgR36iLrsgbwm4mnzwSZd9kbT1MwxoU3WTo6Ce7qGMdMMfLa7ramXMGGWrey1r88QgqtMoWWqVaVLRMGHeN"
        + "m6bEfaNpnYJpLgR4FvEyxNB121xoFo1iA9BSTmUJ1bm5rWgkhXLZjCdT54gnuz7VsthCZmRLSs6hXch6f3C7Gf36ayFmAcuaAVqfu5vqo6a9X"
        + "vWmU"
    /// `{ invitation: <signed>, groupAlias: "general" }`: mero-chat's payload.
    static let chatToken =
        "3LgQqvPGuP2Ea6P5dcV7FRXcfnrVPeQKJ5pJBrQQEUvLeg8RBjT7Nw6cNbxyhhLvvHdT5mrocMJXDzLiVUC22kd4v8rT6vxD6m7bSAwpJ7kn"
        + "qns4Ac2i6Nqt5mXQJrFwywC5gqUf8mHSX6xriR3kCpotoN8MKybA92LmAeCHqWcojqXDyMYMubfzzet91stoJR2RdGs5zRZeK9BTVKyCpaKPQ"
        + "3ZBGxBGVRGGB1e8zB63zkgeX7mpFTAP6JRp76tQ6Yekk1d9HR7AWF2PJDBtgtumpxRcpuqJ9AabDMwXujTG7Kzh2bM4"
    /// Bytes 1...32: the vectors' `group_id`.
    static let namespaceId = (1...32).map { String(format: "%02x", $0) }.joined()

    func testDecodesMeroDesignsToken() throws {
        let decoded = try XCTUnwrap(AppInvitation.decode(token: Self.designToken))
        XCTAssertEqual(decoded.name, "Design Team ✨")
        XCTAssertEqual(decoded.namespaceId, Self.namespaceId)
        XCTAssertEqual(decoded.invitation.inviterSignature, String(repeating: "cd", count: 64))
        XCTAssertEqual(decoded.invitation.invitation.expirationTimestamp, 4_102_444_800)
        XCTAssertEqual(decoded.invitation.invitation.admitters, [String(repeating: "ab", count: 32)])
        XCTAssertEqual(decoded.invitation.applicationId, Array(repeating: 3, count: 32))
    }

    func testDecodesMeroChatsTokenFromALink() throws {
        let link = InviteLink.invitation(token: Self.chatToken, slug: "com.calimero.chat")
        let decoded = try XCTUnwrap(AppInvitation.parse(link, expectedSlug: "com.calimero.chat"))
        XCTAssertEqual(decoded.name, "general")
        XCTAssertEqual(decoded.namespaceId, Self.namespaceId)
    }

    func testRefusesAnotherAppsLink() {
        let link = InviteLink.invitation(token: Self.chatToken, slug: "com.calimero.chat")
        XCTAssertNil(AppInvitation.parse(link, expectedSlug: "com.calimero.mero-design"))
        XCTAssertNotNil(AppInvitation.parse(Self.chatToken, expectedSlug: "com.calimero.mero-design"), "a bare token")
    }

    func testRoundTripsUnderTheChosenNameKey() throws {
        let original = try XCTUnwrap(AppInvitation.decode(token: Self.designToken))
        let renamed = AppInvitation(invitation: original.invitation, name: "Ops")
        let token = try renamed.token(nameKey: "__teamName")
        let json = try XCTUnwrap(InviteCodec.decode(token: token))
        XCTAssertTrue(json.contains(#""__teamName":"Ops""#), json)
        let back = try XCTUnwrap(AppInvitation.decode(token: token))
        XCTAssertEqual(back.name, "Ops")
        XCTAssertEqual(back.namespaceId, Self.namespaceId)
        XCTAssertEqual(back.invitation.inviterSignature, original.invitation.inviterSignature)
        XCTAssertEqual(back.invitation.invitation.secretSalt, original.invitation.invitation.secretSalt)

        let link = try renamed.link(slug: "com.calimero.mero-design")
        XCTAssertEqual(AppInvitation.parse(link, expectedSlug: "com.calimero.mero-design")?.name, "Ops")
    }

    func testTakesABareCamelCaseInvitationInADataEnvelope() throws {
        let group = (1...32).map(String.init).joined(separator: ",")
        let json =
            #"{"data":{"invitation":{"inviter_identity":[],"group_id":[\#(group)],"expiration_timestamp":1,"#
            + #""secret_salt":[]},"inviterSignature":"ff"}}"#
        let decoded = try XCTUnwrap(AppInvitation.decode(json: json))
        XCTAssertNil(decoded.name)
        XCTAssertEqual(decoded.invitation.inviterSignature, "ff")
        XCTAssertEqual(decoded.namespaceId, Self.namespaceId)
    }

    func testRefusesWhatIsNotAnInvitation() {
        XCTAssertNil(AppInvitation.decode(token: "not a token"))
        XCTAssertNil(AppInvitation.decode(json: #"{"invitation":{"group_id":[1]}}"#))
        XCTAssertNil(AppInvitation.parse(""))
    }
}
